private addStructuralCommand(
  id: string,
  name: string,
  op: StructuralOp,
  useMappedCursor = false,
  hotkeys?: Hotkey[],
  /** Outdent is the one operation whose result can leave a zoom scope from a
   * node that is not the root itself, so the guard has to be told. */
  isOutdent = false,
