/** Scratch probe — task 1.1. Deleted before the checkpoint. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const NOTE = 'People/Maya Lindqvist.md';

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
  });

  it('records reading-view getState/setState', async function () {
    const out = await browser.executeObsidian(async ({ app, obsidian }, notePath: string) => {
      const log: unknown[] = [];
      const leaf = app.workspace.getLeaf(true);
      const file = app.vault.getAbstractFileByPath(notePath) as never;
      const snap = () => {
        const v = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
        return {
          state: v ? JSON.parse(JSON.stringify(v.getState())) : null,
          mode: v ? v.getMode() : null,
          hasEditor: !!(v as never as { editor?: unknown })?.editor,
        };
      };
      const settle = () => new Promise((r) => setTimeout(r, 400));

      for (const startSource of [false, true]) {
        await leaf.openFile(file, { state: { mode: 'source', source: startSource } });
        await settle();
        log.push({ step: `opened editing source=${startSource}`, ...snap() });

        const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
        await view.setState({ ...view.getState(), mode: 'preview' }, { history: false });
        await settle();
        log.push({ step: `switched to reading (was source=${startSource})`, ...snap() });

        // What does setState({mode:'source'}) ALONE do — no `source` key at all?
        const v2 = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
        await v2.setState({ mode: 'source' }, { history: false });
        await settle();
        log.push({ step: `setState({mode:'source'}) alone (was source=${startSource})`, ...snap() });
      }

      // And: does spreading the reading state and overriding mode round-trip?
      for (const startSource of [false, true]) {
        await leaf.openFile(file, { state: { mode: 'source', source: startSource } });
        await settle();
        const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
        await view.setState({ ...view.getState(), mode: 'preview' }, { history: false });
        await settle();
        const v2 = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
        await v2.setState({ ...v2.getState(), mode: 'source' }, { history: false });
        await settle();
        log.push({ step: `spread+mode:'source' (was source=${startSource})`, ...snap() });
      }
      return log;
    }, NOTE);
    console.log('PROBE-RESULT ' + JSON.stringify(out, null, 2));
  });
});
