/** Scratch probe — tasks 1.1 and 4.2. Deleted before the checkpoint. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const NOTE = 'People/Maya Lindqvist.md';
const OTHER = 'People/Aria Fontaine.md';

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
  });

  it('records events and preview-mode facts', async function () {
    const out = await browser.executeObsidian(async ({ app, obsidian, plugins }, notePath: string, otherPath: string) => {
      const log: unknown[] = [];
      const events: string[] = [];
      const refs = [
        app.workspace.on('active-leaf-change', () => events.push('active-leaf-change')),
        app.workspace.on('file-open', () => events.push('file-open')),
        app.workspace.on('layout-change', () => events.push('layout-change')),
      ];
      const settle = () => new Promise((r) => setTimeout(r, 500));
      const drain = (step: string, extra?: unknown) => {
        log.push({ step, events: [...events], ...(extra as object) });
        events.length = 0;
      };

      const leaf = app.workspace.getLeaf(true);
      const file = app.vault.getAbstractFileByPath(notePath) as never;
      const other = app.vault.getAbstractFileByPath(otherPath) as never;

      // A leaf opened FRESH straight into preview: what does it record?
      const leaf2 = app.workspace.getLeaf('split');
      await leaf2.openFile(other, { state: { mode: 'preview' } });
      await settle();
      const v0 = leaf2.view as never as { getState(): unknown };
      drain('fresh leaf opened in preview', { state: JSON.parse(JSON.stringify(v0.getState())) });

      app.workspace.setActiveLeaf(leaf, { focus: true });
      await leaf.openFile(file, { state: { mode: 'source', source: false } });
      await settle();
      drain('opened editing');

      const view = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const registryHasEditor = () => {
        const v = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        return !!(v && (plugins.trueOutliner as any).constructor && (v.editor as any)?.cm?.dom?.isConnected);
      };
      log.push({ step: 'editing: editor cm connected', value: registryHasEditor() });

      await view.setState({ ...view.getState(), mode: 'preview' }, { history: false });
      await settle();
      drain('in-leaf switch to reading', {
        mode: app.workspace.getActiveViewOfType(obsidian.MarkdownView)?.getMode(),
        cmConnected: registryHasEditor(),
      });

      const v2 = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      await v2.setState({ ...v2.getState(), mode: 'source' }, { history: false });
      await settle();
      drain('in-leaf switch back to editing', {
        mode: app.workspace.getActiveViewOfType(obsidian.MarkdownView)?.getMode(),
        cmConnected: registryHasEditor(),
      });

      app.workspace.setActiveLeaf(leaf2, { focus: true });
      await settle();
      drain('tab switch to the other leaf');

      for (const r of refs) app.workspace.offref(r);
      return log;
    }, NOTE, OTHER);
    console.log('PROBE-RESULT ' + JSON.stringify(out, null, 2));
  });
});
