import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const NOTE = 'People/Maya Lindqvist.md';
const OTHER = 'People/Aria Fontaine.md';

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
  });

  it('editor identity across mode round-trip and file switch', async function () {
    const out = await browser.executeObsidian(async ({ app, obsidian }, notePath: string, otherPath: string) => {
      const log: unknown[] = [];
      const settle = () => new Promise((r) => setTimeout(r, 500));
      const ids = new Map<unknown, number>();
      const idOf = (o: unknown): number | null => {
        if (!o) return null;
        if (!ids.has(o)) ids.set(o, ids.size + 1);
        return ids.get(o)!;
      };
      const snap = (step: string) => {
        const v = app.workspace.getActiveViewOfType(obsidian.MarkdownView);
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const cm = v ? (v.editor as any)?.cm : undefined;
        log.push({
          step,
          mode: v?.getMode() ?? null,
          state: v ? JSON.parse(JSON.stringify(v.getState())) : null,
          cmId: idOf(cm),
          cmConnected: cm?.dom?.isConnected ?? null,
          infoId: idOf(cm?.state?.field?.(obsidian.editorInfoField, false)),
        });
      };

      const leaf = app.workspace.getLeaf(true);
      const file = app.vault.getAbstractFileByPath(notePath) as never;
      const other = app.vault.getAbstractFileByPath(otherPath) as never;

      await leaf.openFile(file, { state: { mode: 'source', source: false } });
      await settle();
      snap('opened editing (live preview)');

      let v = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      await v.setState({ ...v.getState(), mode: 'preview' }, { history: false });
      await settle();
      snap('-> reading');

      v = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      await v.setState({ ...v.getState(), mode: 'source' }, { history: false });
      await settle();
      snap('-> back to editing');

      await leaf.openFile(other, { state: { mode: 'source', source: false } });
      await settle();
      snap('switched file');

      await leaf.openFile(file, { state: { mode: 'source', source: false } });
      await settle();
      snap('switched back');

      // A leaf opened FRESH straight into preview, settled properly.
      const leaf2 = app.workspace.getLeaf('split');
      await leaf2.openFile(other, { state: { mode: 'preview' } });
      await settle();
      snap('fresh leaf, opened in preview');
      const v3 = app.workspace.getActiveViewOfType(obsidian.MarkdownView)!;
      await v3.setState({ ...v3.getState(), mode: 'source' }, { history: false });
      await settle();
      snap('that leaf -> editing (no source history)');

      return log;
    }, NOTE, OTHER);
    console.log('PROBE-RESULT ' + JSON.stringify(out, null, 2));
  });
});
