/** Scratch probe — is the EditorState recreated? Deleted before the checkpoint. */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as h from '../helpers.js';

const NOTE = 'People/Maya Lindqvist.md';
const OTHER = 'People/Priya Nair.md';

describe('probe', function () {
  before(async function () {
    await obsidianPage.resetVault();
    await h.resetPluginState();
  });

  it('EditorState config identity across switches', async function () {
    const out = await browser.executeObsidian(async ({ app, obsidian }, notePath: string, otherPath: string) => {
      const log: unknown[] = [];
      const settle = () => new Promise((r) => setTimeout(r, 500));
      const ids = new Map<unknown, number>();
      const idOf = (o: unknown): number | null => {
        if (!o) return null;
        if (!ids.has(o)) ids.set(o, ids.size + 1);
        return ids.get(o)!;
      };
      let active = app.workspace.getLeaf(true);
      const view = () =>
        active.view as never as {
          getState(): Record<string, unknown>;
          setState(s: unknown, r: unknown): Promise<void>;
          getMode?(): string;
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          editor?: any;
        };
      const snap = (step: string) => {
        const v = active.view instanceof obsidian.MarkdownView ? active.view : null;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const cm = v ? (v.editor as any)?.cm : undefined;
        log.push({
          step,
          file: v?.file?.path ?? null,
          mode: v?.getMode() ?? null,
          cmId: idOf(cm),
          // The Configuration object: shared across a state CHAIN, replaced by
          // EditorState.create and by a reconfigure. Its identity answers
          // "did the field's create() run again".
          configId: idOf(cm?.state?.config),
          docLen: cm?.state?.doc?.length ?? null,
        });
      };

      const file = app.vault.getAbstractFileByPath(notePath) as never;
      const other = app.vault.getAbstractFileByPath(otherPath) as never;

      await active.openFile(file, { state: { mode: 'source', source: false } });
      await settle();
      snap('opened editing');

      // A plain edit: same chain, so the config must be identical.
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (view().editor as any).setCursor({ line: 0, ch: 0 });
      await settle();
      snap('after a cursor dispatch');

      let v = view();
      await v.setState({ ...v.getState(), mode: 'preview' }, { history: false });
      await settle();
      snap('-> reading');

      v = view();
      await v.setState({ ...v.getState(), mode: 'source' }, { history: false });
      await settle();
      snap('-> back to editing');

      await active.openFile(other, { state: { mode: 'source', source: false } });
      await settle();
      snap('switched file');

      await active.openFile(file, { state: { mode: 'source', source: false } });
      await settle();
      snap('switched back');

      const leaf2 = app.workspace.getLeaf('split');
      active = leaf2;
      await leaf2.openFile(other, { state: { mode: 'source', source: false } });
      await settle();
      snap('a second leaf');

      return log;
    }, NOTE, OTHER);
    console.log('PROBE-RESULT ' + JSON.stringify(out));
  });
});
